-- HISTORICAL (pre-V13). Superseded: V13 renamed Digital Skills to Digital Marketing in migration 20260101000030 (track code kept).
-- This script refuses to run after migration 16, so it cannot undo V13.
-- Replace the OLD curriculum tracks with the current four (Digital Skills, AI Tools, Content Creation, Entrepreneurship & Business).
-- WHY THIS EXISTS: seed.sql uses "on conflict do nothing", so a database that was seeded earlier keeps its old tracks and sessions;
-- the new ones are skipped (same track code) or sit beside the old ones. Re-running seed.sql does not fix that. This script does.
--
-- Run it once in the Supabase SQL Editor (or `psql`). It is ONE transaction: if anything already uses an old track or session
-- (an enrolment, application preference, scheduled session, assignment, resource or course), the delete fails and NOTHING changes.
-- In that case do not force it: tell the developer, because those records need moving to the new tracks first.
-- Shared core sessions (sessions 1 and 2) are not touched.

begin;

-- STOP if the Curriculum Approval Centre exists: topic proposals (and their history) point at sessions, and proposals are never deleted.
do $$ begin
  if to_regclass('public.curriculum_topic_proposals') is not null then
    raise exception 'Do not run this script after the Curriculum Approval Centre migration (20260101000016). Tell the developer.';
  end if;
end $$;

delete from curriculum_sessions
 where programme_id = '00000000-0000-0000-0000-0000000000a1' and track_id is not null;
delete from tracks
 where programme_id = '00000000-0000-0000-0000-0000000000a1';


commit;

